const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const initial={day:3,points:120,energy:6,place:'cabin',inventory:{Egg:2,Berries:2,Herbs:2,Beans:2,Wood:1},cats:[{name:'Juniper',emoji:'🐈',mood:'sleepy · a little nosy',quote:'“That mug looks suspiciously warm. I will investigate.”',hearts:3}],cat:0,plants:[],tasks:[],done:[],streak:3,unlocks:[],furniture:[],visited:{},time:9};
let game;try{game={...initial,...JSON.parse(localStorage.getItem('mosswood-save')||'{}')};game.inventory={...initial.inventory,...(game.inventory||{})};game.cats=game.cats?.length?game.cats:initial.cats;game.done=game.done||[];game.unlocks=game.unlocks||[];game.furniture=game.furniture||[];}catch{game={...initial}}
const taskPool=[{id:'breakfast',name:'Make a little something',sub:'Cook a recipe at home',reward:20},{id:'garden',name:'Check on the garden',sub:'Plant or pick something',reward:15},{id:'woods',name:'Take the long way',sub:'Find something in the woods',reward:20},{id:'cat',name:'Make a friend feel loved',sub:'Spend time with your cat',reward:15},{id:'fire',name:'Gather for later',sub:'Chop a little firewood',reward:15},{id:'drink',name:'A proper coffee break',sub:'Make a specialty drink',reward:15},{id:'movie',name:'Make tonight special',sub:'Set up a movie night',reward:20}];
if(!game.tasks?.length)game.tasks=pickTasks();function pickTasks(){return [...taskPool].sort(()=>Math.random()-.5).slice(0,3).map(t=>t.id)}
function save(){localStorage.setItem('mosswood-save',JSON.stringify(game));renderUI()}
const locations={cabin:['The cabin','YOUR LITTLE CORNER OF THE WORLD','PINECONE CABIN','YOUR HOME, SWEET HOME','EVERYTHING FEELS A LITTLE SLOWER HERE'],garden:['The garden','GROW A LITTLE SOMETHING','THE KITCHEN GARDEN','GOOD THINGS GROW HERE','THE BEES KNOW THE WAY'],woods:['The woods','A PATH WITH NO PARTICULAR PLACE TO BE','MOSSY TRAIL','TAKE THE LONG WAY HOME','WHO KNOWS WHAT YOU MIGHT FIND'],market:['Fern & Fable','THE LITTLE VILLAGE MARKET','FERN & FABLE','A FEW GOOD THINGS, JUST A SHORT WALK AWAY','LOCAL GOODS · KIND PEOPLE'],backyard:['The backyard','TONIGHT, THE STARS ARE THE CEILING','THE BACKYARD','YOUR VERY OWN LITTLE OUTDOOR CINEMA','SLOW EVENINGS, WARM LIGHTS']};
function renderUI(){ $('#points').textContent=game.points;$('#dayNum').textContent=String(game.day).padStart(2,'0');$('#energyText').textContent=`${game.energy} / 6`;$('#energyFill').style.width=`${game.energy/6*100}%`;$('#streak').textContent=game.streak;$('#catName').textContent=game.cats[game.cat].name;$('#catMood').textContent=game.cats[game.cat].mood;$('#catQuote').textContent='“'+game.cats[game.cat].quote.replace(/[“”]/g,'')+'”';$('#catPortrait span').textContent=game.cats[game.cat].emoji;$('#hearts').innerHTML=Array.from({length:5},(_,i)=>`<span class="${i>=game.cats[game.cat].hearts?'empty':''}">${i>=game.cats[game.cat].hearts?'♡':'♥'}</span>`).join(' ');$('#taskList').innerHTML=game.tasks.map(id=>{let t=taskPool.find(x=>x.id===id),d=game.done.includes(id);return `<div class="task ${d?'done':''}" data-task="${id}"><span class="task-check">${d?'✓':''}</span><span class="task-copy"><b>${t.name}</b><small>${t.sub}</small></span><span class="task-reward">+${d?'✓':t.reward+' ✦'}</span></div>`}).join('');$('#taskCount').textContent=`${game.done.length} / 3`;$('#inventory').innerHTML=Object.entries(game.inventory).filter(x=>x[1]>0).map(([k,v])=>`<span class="item-chip">${itemEmoji[k]||'✿'} ${k} ×${v}</span>`).join('')||'<span class="item-chip">Your pockets are empty</span>';let l=locations[game.place];$('#sceneTitle').textContent=l[0];$('#sceneEyebrow').textContent=l[1];$('#locationText').innerHTML=`${l[2]} <small>${l[3]}</small>`;$('#sceneCaption').textContent=l[4];$('#sceneHint').textContent=game.place==='cabin'?'CLICK A SPOT TO EXPLORE':'CLICK THE SCENE OR USE AN ACTION';$('#clock').textContent=`${String(game.time).padStart(2,'0')}:24 ${game.time<12?'AM':'PM'}`;sceneRender();renderActions();activity();}
const itemEmoji={Egg:'🥚',Berries:'🫐',Herbs:'🌿',Beans:'☕',Wood:'🪵',Tomato:'🍅',Carrot:'🥕',Apple:'🍎','Cat food':'🥣',Treats:'🍪',Catnip:'🌱',Seeds:'🌰',Milk:'🥛',Fish:'🐟',S'mores:'🍡'};
function activity(){let a={cabin:['☕','A slow morning','The kettle is warm and '+game.cats[game.cat].name+' is keeping you company.'],garden:['🌱','A little patch of green','Your garden is growing at its own gentle pace.'],woods:['🍄','A walk beneath the trees','The woods are quiet, except for birdsong.'],market:['🧺','A friendly little shop','The shelves are full of useful, lovely things.'],backyard:['✦','An evening under the stars','The string lights are ready when you are.']}[game.place];$('#activityIcon').textContent=a[0];$('#activityTitle').textContent=a[1];$('#activityText').textContent=a[2]}
function renderActions(){let a={cabin:[['🍳','Cook'],['☕','Coffee'],['🪵','Chop wood'],['🎬','Movie night'],['✿','Decorate']],garden:[['🌰','Plant seeds'],['🧺','Harvest'],['🌿','Tend garden']],woods:[['🍄','Forage'],['🐾','Look for cats'],['🪵','Gather wood']],market:[['🧺','Shop supplies'],['🪴','Shop plants'],['🪑','Shop home'],['🐈','Meet cats']],backyard:[['📽','Projector night'],['🔥','Light firepit'],['🍡','Make s’mores']]}[game.place];$('#quickActions').innerHTML=a.map(([e,n])=>`<button data-action-label="${n}">${e} ${n}</button>`).join('')}
const canvas=$('#scene'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const C={sky:'#b9cfb0',sky2:'#d8daa7',leaf:'#718e69',dark:'#405d4b',deep:'#304a3d',wood:'#926d50',wood2:'#b18a62',cream:'#f2e7c7',roof:'#625c4e',red:'#b77e66',grass:'#829d69',grass2:'#9caf79',soil:'#755f49',water:'#85b5ae',sun:'#f3d288'};
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}function px(x,y,c,s=4){rect(x,y,s,s,c)}
function tree(x,y,s=1){let u=8*s;rect(x+3*u,y+6*u,u,5*u,C.wood);rect(x,y+2*u,7*u,5*u,C.leaf);rect(x+u,y,5*u,6*u,C.dark);px(x+u,y+u,'#8ba276',u);px(x+4*u,y+2*u,'#8ba276',u)}
function flower(x,y,c){rect(x+4,y+5,2,7,C.leaf);rect(x,y+2,4,4,c);rect(x+6,y+2,4,4,c);rect(x+3,y-1,4,4,c);rect(x+3,y+5,4,4,c);px(x+3,y+2,'#e6cc86',3)}
function cabin(x,y){rect(x+22,y+35,130,74,'#9e7957');rect(x+15,y+31,143,10,C.roof);rect(x+26,y+20,26,13,C.roof);rect(x+44,y+10,9,19,'#736454');rect(x+62,y+48,25,26,'#efd59b');rect(x+67,y+53,15,16,'#75918a');rect(x+111,y+72,24,37,'#664d3d');rect(x+116,y+77,14,32,'#83634b');px(x+126,y+91,'#ead69a',3);rect(x+19,y+108,143,6,'#735d46');rect(x+19,y+114,143,4,'#e5d8b8');rect(x+28,y+43,118,4,'#b99368');rect(x+92,y+50,4,58,'#876648');rect(x+32,y+86,21,4,'#876648');rect(x+47,y+76,5,21,'#876648');rect(x+35,y+85,17,4,'#876648');rect(x+164,y+91,27,6,C.wood);rect(x+168,y+82,21,9,C.wood2);rect(x+170,y+74,18,8,C.wood);rect(x+156,y+98,46,5,C.dark);}
function ground(){rect(0,0,640,220,C.sky);rect(0,145,640,40,C.sky2);rect(0,176,640,184,C.grass);rect(0,245,640,115,C.grass2);rect(0,320,640,40,'#789263');for(let x=14;x<640;x+=24){px(x,190+(x%3)*7,'#a8b785',4);px(x+8,279+(x%4)*4,'#6f8c62',4)}tree(4,38,1.1);tree(82,57,.8);tree(232,35,1.1);tree(350,55,.8);tree(500,29,1.15);tree(584,58,.9);rect(0,177,640,5,'#9db17f');flower(188,214,'#e9d39a');flower(552,254,'#eee0ba');}
function sceneRender(){let w=640,h=360;ctx.clearRect(0,0,w,h);if(game.place==='cabin'||game.place==='backyard'){ground();if(game.place==='cabin'){cabin(232,94);rect(259,208,112,44,'#b6ad88');rect(267,208,94,5,'#ddd1aa');tree(404,137,.7);rect(187,257,49,6,C.wood);rect(194,248,5,11,C.wood);rect(225,248,5,11,C.wood);rect(182,241,59,5,'#8b7254'); // cat
catSprite(414,251,game.cats[game.cat].emoji);rect(23,318,594,2,'#638256');if(game.furniture.includes('Fern wall shelf')){rect(280,142,40,4,C.wood);flower(291,131,'#e6ca82')}if(game.furniture.includes('String lights')){for(let x=80;x<580;x+=28){rect(x,72,2,18,'#5d6d50');px(x-2,86,'#f2dc9b',5)}}}else{rect(0,287,640,73,'#4e6250');rect(0,290,640,4,'#718268');for(let x=35;x<620;x+=95)tree(x,66+(x%3)*13,.85);rect(56,206,520,95,'#223b3b');rect(66,214,500,77,'#d7c391');rect(81,222,471,60,'#4d6452');rect(88,228,455,47,'#72846a');rect(0,304,640,56,'#465948');rect(75,310,75,8,C.wood);rect(75,318,8,17,C.wood);rect(139,318,8,17,C.wood);rect(489,312,87,9,C.wood);for(let x=505;x<565;x+=18)rect(x,302,6,9,C.wood2);rect(315,300,9,21,'#d49a50');rect(306,316,27,6,'#966443');rect(310,294,18,5,'#eead61');for(let x=45;x<600;x+=55){px(x,195,'#e5dcad',3)} }}else if(game.place==='garden'){ground();for(let x=20;x<620;x+=72)tree(x,20+(x%4)*6,.8);rect(0,208,640,152,'#849b6c');for(let i=0;i<4;i++){rect(62,202+i*35,514,28,'#785f45');rect(64,204+i*35,510,4,'#967755');for(let j=0;j<7;j++){let x=88+j*70,y=211+i*35;if(game.plants.length>i*7+j){let colors=['#72965f','#91a86a','#be7d5e'];rect(x+8,y+5,5,13,C.leaf);rect(x+3,y+8,9,6,colors[(i+j)%3]);px(x+19,y+4,'#739b61',5)}else{rect(x+8,y+5,5,8,'#96a774');px(x+5,y+4,'#b4c386',4)}}}rect(22,330,594,6,'#6f825d');rect(532,72,4,105,C.wood);rect(500,68,72,34,'#f0e2b9');rect(507,75,58,18,'#eee6ca');ctx.fillStyle='#849473';ctx.font='11px monospace';ctx.fillText('GROW SLOW',511,88);flower(32,177,'#efdeaa');flower(603,290,'#e0c3c0');}else if(game.place==='woods'){rect(0,0,640,360,'#a6c19a');rect(0,207,640,153,'#6f8d68');rect(0,280,640,80,'#8da174');for(let i=0;i<12;i++){let x=i*59-18,y=12+(i%4)*27,s=i%3===0?1.2:.88;tree(x,y,s);if(i%2===0){rect(x+12,y+54,4,26,C.wood);rect(x+4,y+51,20,7,'#806848')}}rect(254,201,97,159,'#b3a87c');rect(278,203,45,157,'#c9bb8d');for(let x=40;x<600;x+=81){flower(x,260+(x%3)*10,x%2?'#e1d09f':'#e6d5bd');}rect(454,284,29,13,'#d8d4b5');px(461,278,'#ddd9bc',5);px(471,279,'#d5d0ae',5);if(game.cats.length<2){catSprite(475,267,'🐈‍⬛')}}else{ // market
rect(0,0,640,360,'#c9d4b0');rect(0,205,640,155,'#8fa278');for(let x=0;x<640;x+=88)tree(x,17+(x%3)*20,.75);rect(124,92,390,182,'#d5bd93');rect(112,81,418,23,'#765c48');rect(133,114,371,9,'#a47b58');rect(144,132,116,82,'#e7d8b7');rect(151,139,102,67,'#8ba18a');rect(276,132,118,82,'#eee0bd');rect(284,141,102,66,'#b5c29b');rect(410,132,79,142,'#aa805a');rect(422,146,56,126,'#826449');rect(139,92,359,9,'#bf9665');rect(236,53,175,38,'#f2e7c7');ctx.fillStyle='#61765b';ctx.font='bold 14px monospace';ctx.fillText('FERN & FABLE',249,77);for(let i=0;i<5;i++){rect(151+i*62,176,17,17,['#d58f6e','#d7bd75','#8eaa78','#dfd1a7','#a99abd'][i]);}rect(96,275,454,9,'#7b6349');rect(114,284,10,24,'#765940');rect(520,284,10,24,'#765940');flower(69,309,'#e4d39b');}
// floating fireflies and interactive sparkles
for(let i=0;i<5;i++){let x=(i*127+42)%620,y=155+(i*39)%115;px(x,y,'#e5dfae',3)}
}
function catSprite(x,y,e='🐈'){ctx.font='26px serif';ctx.fillText(e,x,y)}
function spend(n=1){if(game.energy<n){toast('You are all tuckered out. Have a rest at home 🌙');return false}game.energy-=n;game.time=Math.min(21,game.time+1);return true}
let toastTimer;function toast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function complete(id){if(!game.tasks.includes(id)||game.done.includes(id))return;let t=taskPool.find(x=>x.id===id);game.done.push(id);game.points+=t.reward;toast(`Little thing done! +${t.reward} dew drops ✨`)}
const recipes=[{name:'Wild berry pancakes',emoji:'🥞',desc:'Fluffy, with garden berries & a drizzle of honey.',cost:{Egg:1,Berries:1},reward:24,task:'breakfast'},{name:'Herby garden omelette',emoji:'🍳',desc:'Eggs folded with whatever is growing.',cost:{Egg:1,Herbs:1},reward:18,task:'breakfast'},{name:'Iced honey oat latte',emoji:'🧋',desc:'Double espresso, honey, milk & plenty of ice.',cost:{Beans:1,Milk:1},reward:22,task:'drink'},{name:'Campfire berry hand pie',emoji:'🥧',desc:'A tiny pie with warm berries and wild herbs.',cost:{Berries:2,Herbs:1},reward:28,task:'breakfast'}];
function openModal(title,desc,options,foot='Take your time. There is no wrong way to spend a day.'){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-top"><div><div class="eyebrow">A MOMENT TO YOURSELF</div><h2>${title}</h2><p>${desc}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-options">${options.map((o,i)=>`<button class="option" data-opt="${i}" ${o.disabled?'disabled':''} style="${o.disabled?'opacity:.48;cursor:default':''}"><span class="option-emoji">${o.emoji}</span><span class="option-copy"><b>${o.name}</b><small>${o.desc}</small></span><span class="option-cost">${o.cost||'↗'}</span></button>`).join('')}</div><div class="modal-foot"><span>${foot}</span><strong>✦ ${game.points} drops</strong></div></div></div>`;$('#modalRoot .modal-close').onclick=closeModal;$('#modalRoot .modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};$$('#modalRoot .option').forEach(b=>b.onclick=()=>{let o=options[+b.dataset.opt];if(!o.disabled)o.run()})}
function closeModal(){$('#modalRoot').innerHTML=''}
function canPay(cost){return Object.entries(cost||{}).every(([k,v])=>(game.inventory[k]||0)>=v)}function consume(cost){Object.entries(cost||{}).forEach(([k,v])=>game.inventory[k]-=v)}
function cook(){openModal('What sounds good?','The kitchen is sunny, and you have just enough time to make something lovely.',recipes.map(r=>({emoji:r.emoji,name:r.name,desc:r.desc,cost:canPay(r.cost)?Object.entries(r.cost).map(([k,v])=>`${v} ${k}`).join(' · '):'You need '+Object.keys(r.cost).filter(k=>(game.inventory[k]||0)<r.cost[k]).join(', '),disabled:!canPay(r.cost),run:()=>{if(!spend())return;consume(r.cost);game.inventory['Cat food']=(game.inventory['Cat food']||0)+1;game.points+=r.reward;complete(r.task);toast(`${r.name} made! A little portion saved for ${game.cats[game.cat].name}. +${r.reward} drops`);closeModal();save()}})),'Cooking takes 1 energy · a little extra is tucked away for your cat.')}
function act(label){switch(label){case'Cook':return cook();case'Coffee':return drink();case'Chop wood':return chop();case'Movie night':return movie();case'Decorate':return decorate();case'Plant seeds':return plant();case'Harvest':return harvest();case'Tend garden':return tend();case'Forage':return forage();case'Look for cats':return explore();case'Gather wood':return chop();case'Shop supplies':return shop('supplies');case'Shop plants':return shop('plants');case'Shop home':return shop('home');case'Meet cats':return shop('cats');case'Projector night':return movie(true);case'Light firepit':return fire();case'Make s’mores':return smores();}}
function drink(){openModal('A little coffee ritual','A specialty iced espresso, the signature drink of Pinecone Cabin.',[{emoji:'🧋',name:'Honey oat iced espresso',desc:'A double shot over ice with honey & oat milk.',cost:canPay({Beans:1})?'1 coffee bean':'Need coffee beans',disabled:!canPay({Beans:1}),run:()=>{if(!spend())return;consume({Beans:1});game.points+=14;complete('drink');toast('Iced espresso, just right. +14 dew drops');closeModal();save()}},{emoji:'☕',name:'Pour-over, slow & easy',desc:'A simple warm cup for a thoughtful morning.',cost:canPay({Beans:1})?'1 coffee bean':'Need coffee beans',disabled:!canPay({Beans:1}),run:()=>{if(!spend())return;consume({Beans:1});toast('A warm cup, and nowhere else to be.');closeModal();save()}}])}
function chop(){openModal('A little wood for later','The chopping block is dry. One good bundle is plenty.',[{emoji:'🪓',name:'Chop a bundle of firewood',desc:'Good for a chilly evening or a glowing firepit.',cost:'1 energy',run:()=>{if(!spend())return;game.inventory.Wood=(game.inventory.Wood||0)+2;complete('fire');toast('Two neat bundles for the woodpile.');closeModal();save()}}])}
function plant(){openModal('What shall we grow?','A small seed becomes a whole season of good things.',[{emoji:'🍅',name:'Plant tomatoes',desc:'Sweet little tomatoes · 2 days to grow.',cost:canPay({Seeds:1})?'1 seed':'1 seed (buy some at the market)',disabled:!canPay({Seeds:1}),run:()=>{if(!spend())return;consume({Seeds:1});game.plants.push({name:'Tomato',day:game.day+2,emoji:'🍅'});complete('garden');toast('Tomatoes planted. Give them a couple of sunny days.');closeModal();save()}},{emoji:'🥕',name:'Plant carrots',desc:'Crunchy carrots · 1 day to grow.',cost:canPay({Seeds:1})?'1 seed':'1 seed (buy some at the market)',disabled:!canPay({Seeds:1}),run:()=>{if(!spend())return;consume({Seeds:1});game.plants.push({name:'Carrot',day:game.day+1,emoji:'🥕'});complete('garden');toast('A row of carrots, tucked into the soil.');closeModal();save()}}])}
function harvest(){let ready=game.plants.filter(p=>p.day<=game.day);if(!ready.length){toast(game.plants.length?'Not quite ready yet. Give them a little more time 🌱':'Nothing to pick just yet. Try planting seeds!');return}if(!spend())return;ready.forEach(p=>{game.inventory[p.name]=(game.inventory[p.name]||0)+2;game.plants.splice(game.plants.indexOf(p),1)});complete('garden');toast('A lovely harvest, fresh from your garden!');save()}
function tend(){if(!spend())return;game.plants.forEach(p=>p.day=Math.max(game.day,p.day-1));game.inventory.Herbs=(game.inventory.Herbs||0)+1;complete('garden');toast('You pulled a few weeds and snipped some herbs 🌿');save()}
function forage(){openModal('A walk in the woods','You tuck your hands into your pockets and follow the mossy path.',[{emoji:'🍄',name:'Follow the fern trail',desc:'Look for berries, herbs, and other forest treasures.',cost:'1 energy',run:()=>{if(!spend())return;let finds=[['Berries',2],['Herbs',2],['Apple',1],['Mushrooms',2]];let [n,q]=finds[Math.floor(Math.random()*finds.length)];game.inventory[n]=(game.inventory[n]||0)+q;complete('woods');toast(`You found ${q} ${n.toLowerCase()}! 🌿`);closeModal();save()}},{emoji:'🪵',name:'Gather fallen branches',desc:'Only take what the forest has already let go.',cost:'1 energy',run:()=>{if(!spend())return;game.inventory.Wood=(game.inventory.Wood||0)+1;complete('woods');toast('One good dry branch for the firewood pile.');closeModal();save()}}])}
function explore(){if(game.cats.length<2&&game.day>=3){openModal('A tiny rustle in the ferns','A little black cat watches you from the path. They look cautious, but curious.',[{emoji:'🐈‍⬛',name:'Leave a little fish nearby',desc:'Give this shy newcomer a reason to trust you.',cost:canPay({Fish:1})?'1 fish':'Find or buy fish first',disabled:!canPay({Fish:1}),run:()=>{if(!spend())return;consume({Fish:1});game.cats.push({name:'Pepper',emoji:'🐈‍⬛',mood:'shy · secretly a sweetheart',quote:'“I was only here for the fish. And perhaps your company.”',hearts:1});complete('woods');toast('Pepper has decided to come home with you! 🖤');closeModal();save()}}],'New friends arrive when they are ready.');return}openModal('A tiny rustle in the ferns','You hear something between the roots. Maybe a friend, maybe just a very determined squirrel.',[{emoji:'🐾',name:'Leave a little snack',desc:'A gentle hello, with no pressure to stay.',cost:canPay({'Cat food':1})?'1 cat meal':'Make a meal at home first',disabled:!canPay({'Cat food':1}),run:()=>{if(!spend())return;consume({'Cat food':1});game.cats[game.cat].hearts=Math.min(5,game.cats[game.cat].hearts+1);toast('A small pawprint by the trail. Someone appreciated that.');complete('woods');closeModal();save()}}])}
const stock={supplies:[['🥚','Farm eggs', 'A half-dozen from the neighbor’s hens.',12,{Egg:3}],['🫐','Wild blueberries','Picked just up the ridge.',10,{Berries:3}],['☕','Coffee beans','Dark roast from a kind local.',16,{Beans:3}],['🥛','Oat milk','For something lovely over ice.',9,{Milk:2}],['🐟','Little fish','For a new friend in the ferns.',18,{Fish:1}],['🌿','Garden herbs','A fragrant little bundle.',8,{Herbs:3}],['🥣','Cat supper','A wholesome pantry staple.',14,{'Cat food':2}],['🌰','Seed packet','A surprise mix for your beds.',10,{Seeds:3}],['🍪','Salmon treats','A tiny treat for a very good cat.',12,{Treats:2}],['🌱','Catnip seeds','For a happy garden cat.',10,{Catnip:2}]],plants:[['🍅','Tomato starter','A sun-loving old favorite.',18,{Seeds:2}],['🥕','Carrot starter','Crunchy roots for later.',14,{Seeds:2}],['🍓','Strawberry runner','A sweet little groundcover.',25,{Seeds:2}]],home:[['🪴','Fern wall shelf','A tiny home for a little plant.',55,'Fern wall shelf'],['✨','String lights','A warm twinkle for slow evenings.',70,'String lights'],['🪑','Wicker reading chair','The perfect rainy-day corner.',80,'Wicker chair']],cats:[['🐈‍⬛','Meet Pepper','A shy friend with a brave little heart.',40,'cat']]};
